/* Campaign views use the progression model's public mutations. */
(function(root){
  'use strict';
  const ui={tab:'hub',selected:null,compare:null,search:'',tier:'all',position:'all',sort:'value',page:0,affordable:false,notice:'',draft:null,rookies:[],release:null,importPreview:null,importReadId:0};
  const tabs=[['hub','Clubhouse'],['roster','Roster'],['develop','Development'],['market','Scouting'],['schedule','Road to glory'],['strategy','Game plan'],['training','Training'],['stats','Statistics']];
  const offenses={motion:'Motion',pick_roll:'Pick & Roll',pick_pop:'Pick & Pop',drive_kick:'Drive & Kick',isolation:'Isolation',give_go:'Give & Go',post_up:'Post Up',fast_break:'Fast Break'};
  const defenses={balanced:'Balanced coverage',protect_paint:'Protect the paint',perimeter:'Protect the perimeter',pressure:'Pressure the ball',switch:'Switch screens'};
  const logos={comet:'Comets',crown:'Crown',falcon:'Flight',bolt:'Voltage',shield:'Guardians',orbit:'Orbit'};
  let screen=null,preview=null,frameId=0,observer=null;
  const api=()=>root.RiseToGlory;
  const state=()=>typeof riseState!=='undefined'?riseState:null;
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=value=>Math.round(Number(value)||0);
  const title=value=>String(value??'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_-]/g,' ').replace(/\b\w/g,x=>x.toUpperCase());
  const money=value=>num(value).toLocaleString()+' C';
  // Team colors remain on uniforms and emblems; interface accents must read on every dark panel.
  function readableAccent(value,fallback){
    if(!/^#[0-9a-f]{6}$/i.test(value||''))return fallback;
    const channels=value.slice(1).match(/../g).map(c=>parseInt(c,16)/255).map(c=>c<=.04045?c/12.92:Math.pow((c+.055)/1.055,2.4));
    const luminance=channels[0]*.2126+channels[1]*.7152+channels[2]*.0722;
    return (luminance+.05)/(.0609+.05)>=4.5?value:fallback;
  }
  const roster=()=>api().roster(state());
  const athlete=id=>api().player(state(),id);
  const selected=()=>athlete(ui.selected)||roster()[0];
  const archetype=p=>api().ARCHETYPES[p.archetype]?.name||title(p.archetype);
  const attrs=()=>Object.entries(api().ATTRIBUTES);
  const avg=(p,items)=>num(items.reduce((s,a)=>s+p.ratings[a.key],0)/items.length);
  const division=()=>api().DIVISIONS[state().season.division];
  const option=(map,current)=>Object.entries(map).map(([key,label])=>`<option value="${esc(key)}"${key===current?' selected':''}>${esc(label)}</option>`).join('');
  const button=(label,action,extra='',style='')=>`<button type="button" class="rise-button ${style}" data-rise="${action}" ${extra}>${label}</button>`;
  const bar=(value,max=100)=>`<span class="rise-bar"><i style="width:${Math.max(0,Math.min(100,value/Math.max(1,max)*100))}%"></i></span>`;
  const metric=(label,value,detail='')=>`<div class="rise-metric"><small>${esc(label)}</small><strong>${esc(value)}</strong>${detail?`<span>${esc(detail)}</span>`:''}</div>`;
  const heading=(kicker,name,copy='',action='')=>`<div class="rise-heading"><div><p class="rise-kicker">${esc(kicker)}</p><h2>${esc(name)}</h2>${copy?`<p>${esc(copy)}</p>`:''}</div>${action}</div>`;
  const graphic=(method,key,options={})=>root.RiseGraphics?.[method]?.(key,options)||'';
  const icon=key=>graphic('icon',key);
  const art=(kind,className='')=>`<img class="rise-editorial-art ${className}" src="assets/campaign/rise-${kind}.webp" alt="" aria-hidden="true" loading="lazy" decoding="async" width="1600" height="640">`;
  const artHeading=(kicker,name,copy,kind,action='')=>`<section class="rise-art-heading rise-art-heading-${kind}">${art(kind)}${heading(kicker,name,copy,action)}</section>`;
  const archetypeMark=p=>graphic('archetype',p.archetype);
  function lineupGraphic(){
    const players=state().starters.map(athlete);
    return `<figure class="rise-lineup-board"><div class="rise-lineup-court">${root.RiseGraphics?.court?.({label:'Three-player spacing and passing lanes'})||''}</div><figcaption><span class="rise-kicker">SPACE THE FLOOR. SHARE THE BALL.</span><strong>Three pieces. One unit.</strong><div class="rise-lineup-legend">${players.map((p,i)=>`<div><b>${i+1}</b>${archetypeMark(p)}<span><strong>${esc(p.name)}</strong><small>${esc(title(p.role))} · ${esc(p.position)}</small></span></div>`).join('')}</div><p>Give every athlete a clear role. Balance scoring, creation, and defense.</p></figcaption></figure>`;
  }
  function logo(key='comet',label='Team emblem'){
    const paths={comet:'<path d="M12 49 43 18l-8 22 17-5-31 29 8-21Z"/><path class="rise-logo-line" d="m12 17 12 5M6 28l12 2M36 63l8 4"/>',crown:'<path d="m10 25 14 9 12-18 12 18 14-9-8 30H18Z"/><path class="rise-logo-line" d="M21 62h30M24 46h24"/>',falcon:'<path d="m36 24 10 10 23-14-11 25-22 15-22-15L3 20l23 14Z"/><path class="rise-logo-line" d="m15 34 15 10m27-10L42 44M36 39v14"/>',bolt:'<path d="M39 9 15 40h17l-4 23 28-34H39l8-20Z"/><path class="rise-logo-line" d="m14 57 6 6m35-48 6 6"/>',shield:'<path d="M36 9 60 19v21L36 65 12 40V19Z"/><path class="rise-logo-cut" d="m36 23 5 10 11 2-8 8 2 11-10-5-10 5 2-11-8-8 11-2Z"/>',orbit:'<circle cx="36" cy="36" r="15"/><ellipse class="rise-logo-line" cx="36" cy="36" rx="32" ry="13" transform="rotate(-38 36 36)"/><path class="rise-logo-cut" d="M21 36h30M36 21v30"/>'};
    return `<svg class="rise-logo" viewBox="0 0 72 72" role="img" aria-label="${esc(label)}">${paths[key]||paths.comet}</svg>`;
  }
  function portrait(p,small=false){
    const a=p.appearance||{},hex=v=>typeof v==='number'?'#'+v.toString(16).padStart(6,'0'):v;
    const skin=hex(a.skin??0xb87950),hair=hex(a.hair??0x211b1a),color=state()?.team.primaryColor||ui.draft?.primaryColor||'#6aa8e8';
    const fallback=`<svg class="rise-portrait-fallback" viewBox="0 0 120 130" aria-hidden="true" focusable="false"><path d="M11 132v-21q4-20 29-24h40q25 4 29 24v21" fill="${esc(color)}"/><path d="m40 86 20 16 20-16-9-4H49Z" fill="${esc(skin)}"/><path d="m40 88 20 19 20-19M32 94v36m56-36v36" fill="none" stroke="#eef2ff" stroke-width="3" opacity=".7"/><rect x="50" y="69" width="20" height="25" rx="8" fill="${esc(skin)}"/><ellipse cx="60" cy="52" rx="24" ry="29" fill="${esc(skin)}"/><path d="M35 49V36q2-24 25-24 28 0 26 34l-7-15q-20 7-36 1Z" fill="${esc(hair)}"/><path d="M48 51h5m15 0h5m-20 17q7 5 14 0" stroke="#322522" stroke-width="2" stroke-linecap="round"/><text x="60" y="128" text-anchor="middle" fill="white" font-size="23" font-family="Arial" font-weight="900">${esc(a.number??23)}</text></svg>`;
    const photo=root.RisePortraits?.select(p);
    if(!photo)return fallback.replace('class="rise-portrait-fallback"','class="rise-portrait '+(small?'is-small':'')+'"').replace('aria-hidden="true" focusable="false"','role="img" aria-label="'+esc(p.name)+' jersey portrait"');
    return `<span class="rise-portrait rise-headshot ${small?'is-small':''}" role="img" aria-label="${esc(p.name)} face portrait">${fallback}<img class="rise-headshot-image" data-rise-portrait="${esc(photo.id)}" src="${esc(photo.src)}" alt="" aria-hidden="true" width="512" height="512" loading="lazy" decoding="async"><span class="rise-portrait-number" aria-hidden="true">${esc(a.number??23)}</span></span>`;
  }
  function topSkills(p){return Object.entries(p.ratings).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([key,value])=>`<span>${esc(title(key))}<b>${num(value)}</b></span>`).join('');}
  function abilityChips(p){const owned=Object.entries(p.abilities).filter(([,rank])=>rank>0);return owned.length?owned.map(([key,rank])=>`<span class="rise-chip">${graphic('ability',key)}${esc(api().ABILITIES[key]?.name||title(key))} ${'◆'.repeat(Math.min(3,rank))}</span>`).join(''):'<span class="rise-muted">Develop signature abilities in the gym.</span>';}
  const roleHelp={balanced:'Reads the floor using ratings and learned skills.',primary:'Creates advantages as a first scoring option.',shooter:'Spaces beyond the arc and looks for open catch-and-shoots; moves or passes against tight coverage.',playmaker:'Creates passing lanes and looks for a teammate advantage.',slasher:'Cuts and drives into open gaps toward the rim.',anchor:'Seals and screens inside, posts up favorable matchups, and kicks out against help.',stopper:'Tracks dangerous perimeter scorers and contests their space.',sixth_man:'Brings a scoring option off the bench, guided by their skills.'};
  const assignmentHint=p=>`<small class="rise-assignment-hint">${esc(roleHelp[p.role]||roleHelp.balanced)}</small>`;
  const roleOptions=role=>option(Object.fromEntries(api().ROLES.map(r=>[r,title(r)])),role);
  function card(p,kind='roster'){
    const starter=state()?.starters.includes(p.id),captain=state()?.captainId===p.id;
    const actions=kind==='rookie'?button(ui.draft.starterIds.includes(p.id)?'✓ Selected':'Add to starters','rookie',`data-id="${esc(p.id)}" aria-pressed="${ui.draft.starterIds.includes(p.id)}"`,ui.draft.starterIds.includes(p.id)?'is-primary':''):kind==='market'?button('Scout athlete','scout',`data-id="${esc(p.id)}"`)+button(money(p.signingCost)+' · Sign','sign',`data-id="${esc(p.id)}" ${state().currency<p.signingCost||state().roster.length>=10?'disabled':''}`,'is-primary'):button('Develop','develop',`data-id="${esc(p.id)}"`)+button('Compare','compare',`data-id="${esc(p.id)}"`);
    return `<article class="rise-player-card ${starter?'is-starter':''} ${kind==='rookie'&&ui.draft.starterIds.includes(p.id)?'is-picked':''}"><div class="rise-player-art">${portrait(p)}<span class="rise-player-archetype" title="${esc(archetype(p))}">${archetypeMark(p)}</span><div class="rise-overall"><strong>${p.overall}</strong><small>OVR</small></div><span class="rise-card-status">${captain?'CAPTAIN':starter?'STARTER':kind==='rookie'?'ROOKIE':esc(p.tier)}</span></div><div class="rise-player-copy"><small>${esc(p.position)} · ${esc(archetype(p))}</small><h3>${esc(p.name)}</h3><p class="rise-player-meta">Age ${p.age} · ${p.physical.heightCm} cm · ${p.physical.weightKg} kg</p><div class="rise-top-skills">${topSkills(p)}</div><p class="rise-potential">Potential <b>${p.potential}</b> · ${esc(api().ARCHETYPES[p.secondaryArchetype]?.name||'Versatile')}</p><div class="rise-card-abilities">${Object.entries(p.abilities).filter(([,rank])=>rank>0).slice(0,2).map(([key,rank])=>`<span>${graphic('ability',key)}${esc(api().ABILITIES[key].name)} ${'◆'.repeat(rank)}</span>`).join('')||`<small>Signature path: ${esc(api().ABILITIES[p.abilityPotential[0]]?.name||'Develop in training')}</small>`}</div>${kind==='roster'?`<label class="rise-role">Assignment<select data-rise-change="role" data-id="${esc(p.id)}">${roleOptions(p.role)}</select>${assignmentHint(p)}</label>`:''}<div class="rise-card-actions">${actions}</div></div></article>`;
  }
  function save(message='Team updated.') {const result=api().save(state());ui.notice=result.ok?message:result.message;}
  function mutate(method,...args){const result=api()[method](state(),...args);if(!result.ok){ui.notice=result.message;render();return false;}save(result.message);render();return true;}
  function makeDraft(){ui.rookies=api().rookiePool();ui.draft={name:'Northside Comets',primaryColor:'#6aa8e8',secondaryColor:'#f2b19a',jerseyStyle:'classic',logo:'comet',offense:'motion',defense:'balanced',captainName:ui.rookies[0].name,captainNumber:23,starterIds:ui.rookies.slice(0,3).map(p=>p.id)};}
  function creation(){
    if(!ui.draft)makeDraft();const d=ui.draft;
    return `${artHeading('A NEW FRANCHISE STARTS HERE','Build something worth believing in.','Three rookies. One captain. A whole career ahead of you.','hero',button('Import save','import-open'))}<form id="riseCreationForm"><div class="rise-create-start"><span>Street League / 720 C opening budget</span><button type="submit" class="rise-button is-primary" ${d.starterIds.length===3?'':'disabled'}>Create franchise →</button></div><div class="rise-create-grid"><section class="rise-panel"><h3>01 / Club identity</h3><label>Team name<input name="name" value="${esc(d.name)}" maxlength="32" required autocomplete="off"></label><div class="rise-form-pair"><label>Primary color<input type="color" name="primaryColor" value="${d.primaryColor}"></label><label>Secondary color<input type="color" name="secondaryColor" value="${d.secondaryColor}"></label></div><label>Jersey style<select name="jerseyStyle">${option({classic:'Classic trim',stripe:'Center stripe',split:'Split colors',chevron:'Chevron'},d.jerseyStyle)}</select></label><span class="rise-field-label">Choose your emblem</span><div class="rise-logo-options">${Object.entries(logos).map(([key,name])=>`<button type="button" data-rise="logo" data-id="${key}" aria-label="${name} emblem" aria-pressed="${key===d.logo}" class="${key===d.logo?'selected':''}">${logo(key)}<small>${name}</small></button>`).join('')}</div></section><section class="rise-panel"><h3>02 / Make it your team</h3><label>Offensive identity<select name="offense">${option(offenses,d.offense)}</select></label><label>Defensive philosophy<select name="defense">${option(defenses,d.defense)}</select></label><label>Captain name<input name="captainName" maxlength="28" value="${esc(d.captainName)}" required></label><div class="rise-form-pair"><label>Captain jersey number<input name="captainNumber" type="number" min="0" max="99" value="${d.captainNumber}"></label><label>Captain hairstyle<select name="captainHairStyle">${option({shortFade:'Short fade',buzz:'Buzz cut',braids:'Braids',afro:'Afro',spiky:'Spiky',headband:'Headband'},d.captainHairStyle||'shortFade')}</select></label></div><label>Captain appearance<select name="captainSkin">${option({6108197:'Deep brown',13141083:'Warm brown',7357223:'Brown',14789242:'Light tan',4006936:'Dark brown',9393975:'Medium brown',13933162:'Tan'},String(d.captainSkin||13141083))}</select></label><div class="rise-create-brand">${logo(d.logo,d.name+' emblem')}<div><span class="rise-kicker">YOUR LEGACY BEGINS IN</span><strong>Street League</strong><p>Starter contracts are included. Keep your opening budget for a specialist.</p></div></div></section></div>${heading('03 / THE FOUNDING THREE','Select your first squad.','Choose three rookies. Your first selection becomes your customized captain.')}<div class="rise-player-grid">${ui.rookies.map(p=>card(p,'rookie')).join('')}</div><div class="rise-create-footer"><p><b>${d.starterIds.length} / 3</b> starters selected</p><button type="button" data-rise="create-submit" class="rise-button is-primary" ${d.starterIds.length===3?'':'disabled'}>Create franchise →</button></div></form>`;
  }
  function match(){const game=api().nextGame(state());return {game,opponent:game?api().opponent(state(),game):null};}
  function theirOverall(opponent){return opponent?.players.length?num(opponent.players.reduce((s,p)=>s+p.overall,0)/opponent.players.length):'—';}
  function standings(){return `<div class="rise-table-scroll"><table class="rise-table"><thead><tr><th>#</th><th>Club</th><th>W</th><th>L</th></tr></thead><tbody>${api().getStandings(state()).map((row,i)=>`<tr class="${row.id==='player'?'is-your-team':''}"><td>${i+1}</td><th scope="row">${esc(row.name)}</th><td>${row.wins}</td><td>${row.losses}</td></tr>`).join('')}</tbody></table></div>`;}
  function hub(){
    const s=state(),star=athlete(s.captainId),{game,opponent}=match(),c=api().chemistry(s.starters.map(athlete));
    return `<section class="rise-club-hero">${art('hero','rise-club-art')}<div class="rise-club-title"><div class="rise-club-division">${graphic('division',division().id)}<span class="rise-kicker">SEASON ${s.season.number}<br>${esc(division().name)}</span></div><div class="rise-team-lockup">${logo(s.team.logo,s.team.name+' emblem')}<h2>${esc(s.team.name)}</h2></div><p>Built on the blacktop.<br><strong>Bound for the championship.</strong></p><div class="rise-hero-metrics">${metric('Team overall',c.overall)}${metric('Career record',`${s.record.wins}–${s.record.losses}`)}${metric('Chemistry',c.score)}</div></div><div class="rise-featured-player"><div id="riseModelPreview" class="rise-model-preview" aria-label="3D preview of ${esc(star.name)}">${portrait(star)}</div><div class="rise-featured-caption"><span class="rise-kicker">THE FRANCHISE CORNERSTONE</span><strong>${esc(star.name)}</strong><small>${esc(archetype(star))} · ${star.overall} OVR · Level ${star.level}</small></div></div></section><div class="rise-hub-grid"><section class="rise-panel rise-match-panel"><div class="rise-section-label"><span class="rise-kicker">NEXT ON THE SCHEDULE</span><span class="rise-chip">${esc(game?.kind||'Season complete')}</span></div><h3>${esc(opponent?.name||'Bring on the next season.')}</h3><p>${esc(opponent?.identity||'Review your roster and return stronger for your next season.')}</p><div class="rise-match-numbers">${metric('Opponent OVR',theirOverall(opponent))}${metric('Format',game?`${game.teamSize}v${game.teamSize}`:'Offseason')}${metric('Division reward',money(division().reward))}</div><div class="rise-actions">${game?button('Play next game →','tab','data-tab="strategy"','is-primary'):button('Begin next season →','advance','','is-primary')}${button('View schedule','tab','data-tab="schedule"')}</div></section><section class="rise-panel">${heading('THE LONG GAME','Keep getting better')}${button(`${icon('develop')}${roster().reduce((n,p)=>n+p.upgradePoints,0)} upgrade points available ↗`,'tab','data-tab="develop"','rise-hub-link')}${button(`${icon('market')}${api().market(s).length} athletes in scouting ↗`,'tab','data-tab="market"','rise-hub-link')}${button(`${icon('training')}Earn development XP in training ↗`,'tab','data-tab="training"','rise-hub-link')}<p class="rise-muted">${esc(c.strengths.join(' + '))} lead your team. Target ${esc(c.weaknesses.join(' + '))} in recruitment.</p></section></div><div class="rise-hub-grid"><section class="rise-panel">${heading('EVERY GAME COUNTS','Division standings')}${standings()}</section><section class="rise-panel">${heading('FORM GUIDE','Recent results')}${s.season.completed.length?s.season.completed.slice(-4).reverse().map(g=>`<div class="rise-result"><span class="rise-result-badge ${g.won?'is-win':''}">${g.won?'W':'L'}</span><div><strong>${esc(g.opponentName)}</strong><small>${esc(g.kind)}</small></div><b>${g.homeScore}–${g.awayScore}</b></div>`).join(''):'<div class="rise-empty"><strong>Write the first chapter.</strong><p>Your completed games and rivalry results will appear here.</p></div>'}${s.lastReward?`<div class="rise-reward">${esc(s.lastReward.message||s.lastReward.label||s.lastReward.name||'Your team earned a new reward.')}</div>`:''}</section></div>`;
  }
  function lineup(){return `<div class="rise-lineup">${state().starters.map((id,i)=>`<label><span>STARTER ${i+1}${i===0?' / YOU CONTROL':''}</span><select data-rise-change="lineup" data-slot="${i}">${roster().map(p=>`<option value="${esc(p.id)}"${p.id===id?' selected':''}>${esc(p.name)} · ${p.overall} ${p.position}</option>`).join('')}</select></label>`).join('')}</div>`;}
  function picker(){return `<label class="rise-player-picker">Selected athlete<select data-rise-change="selected">${roster().map(p=>`<option value="${esc(p.id)}"${p.id===selected().id?' selected':''}>${esc(p.name)} · ${p.overall} OVR · ${p.upgradePoints} UP</option>`).join('')}</select></label>`;}
  function comparison(){
    const left=selected(),pool=[...roster(),...api().market(state())],right=pool.find(p=>p.id===ui.compare)||pool.find(p=>p.id!==left.id)||left;
    return `<section class="rise-panel rise-compare">${heading('THE RIGHT FIT MATTERS','Compare athletes')}<div class="rise-form-pair"><label>Your athlete<select data-rise-change="selected">${roster().map(p=>`<option value="${p.id}"${p.id===left.id?' selected':''}>${esc(p.name)} · ${p.overall} OVR</option>`).join('')}</select></label><label>Compare with<select data-rise-change="compare">${pool.map(p=>`<option value="${p.id}"${p.id===right.id?' selected':''}>${esc(p.name)} · ${p.overall} OVR</option>`).join('')}</select></label></div><div class="rise-table-scroll"><table class="rise-table"><thead><tr><th>Category</th><th>${esc(left.name)}</th><th>${esc(right.name)}</th><th>Difference</th></tr></thead><tbody>${attrs().map(([key,items])=>{const a=avg(left,items),b=avg(right,items);return `<tr><th>${esc(key)}</th><td>${a}</td><td>${b}</td><td class="${a>=b?'rise-positive':'rise-negative'}">${a>b?'+':''}${a-b}</td></tr>`;}).join('')}</tbody></table></div><p class="rise-muted">${esc(archetype(left))} vs ${esc(archetype(right))} · ${left.potential} vs ${right.potential} potential.</p></section>`;
  }
  function rosterView(){return `${heading('THE WHOLE SQUAD',`${state().roster.length} athletes. One identity.`,'Choose three starters, assign clear roles, and keep a specialist on the bench.')}<section class="rise-panel"><h3>Your starting lineup</h3>${lineupGraphic()}${lineup()}</section><div class="rise-player-grid">${roster().map(p=>card(p)).join('')}</div>${comparison()}`;}
  function development(){
    const p=selected(),next=api().xpRequired(p.level);
    return `${heading('MAKE YOUR OWN SUPERSTAR','Earn the next level.','Every rating, ability, and physical limit carries through to the court.',picker())}<div class="rise-development-grid"><aside class="rise-panel rise-athlete-detail"><div id="riseModelPreview" class="rise-model-preview" aria-label="3D preview of ${esc(p.name)}">${portrait(p)}</div><div class="rise-detail-name"><strong>${p.overall} <small>OVR</small></strong><h3>${esc(p.name)}</h3><p>${esc(p.position)} · ${esc(archetype(p))}</p></div><div class="rise-xp"><span>LEVEL ${p.level}</span><b>${p.upgradePoints} upgrade points</b>${bar(p.xp,next)}<small>${p.xp} / ${next} XP to next level</small></div><div class="rise-chips">${abilityChips(p)}</div><div class="rise-assignment-detail"><label>Assignment<select data-rise-change="role" data-id="${esc(p.id)}">${roleOptions(p.role)}</select></label>${assignmentHint(p)}</div>${Object.keys(p.trainingTokens||{}).length?`<div class="rise-reward"><b>Mastery tuition earned</b><p>${Object.keys(p.trainingTokens).map(key=>esc(api().ABILITIES[key]?.name||title(key))).join(' · ')} — first rank is free once rating requirements and specialization limits are met.</p></div>`:''}<p class="rise-muted">Potential ${p.potential}. Physical ceilings and two ability branches preserve each athlete’s identity.</p><details class="rise-cosmetics"><summary>Jersey & accessories</summary><form id="riseCosmeticsForm"><label>Team jersey style<select name="jerseyStyle">${option({classic:'Classic trim',stripe:'Center stripe',split:'Split colors',chevron:'Chevron'},state().team.jerseyStyle)}</select></label><label>Championship uniform<select name="cosmetic">${option({classic:'Club colors',...Object.fromEntries(state().cosmetics.filter(key=>key!=='classic').map(key=>[key,title(key)]))},state().team.cosmetic||'classic')}</select></label><div class="rise-form-pair"><label>Primary color<input type="color" name="primaryColor" value="${state().team.primaryColor}"></label><label>Secondary color<input type="color" name="secondaryColor" value="${state().team.secondaryColor}"></label></div><label>Jersey number<input name="number" type="number" min="0" max="99" value="${p.appearance.number}"></label><label>Headband<select name="headband">${option({off:'No headband',on:'Team color headband'},p.equipment?.headband?.enabled?'on':'off')}</select></label><label>Shooting sleeve<select name="sleeve">${option({off:'No sleeve',on:'Team color sleeve'},p.equipment?.sleeve?.enabled?'on':'off')}</select></label><button class="rise-button" type="submit">Save appearance</button></form></details>${state().roster.length>3&&!state().starters.includes(p.id)&&state().captainId!==p.id?`<div class="rise-release">${button(ui.release===p.id?'Confirm release athlete':'Release bench athlete','release',`data-id="${p.id}"`,'is-danger')}${ui.release===p.id?button('Keep athlete','cancel-release'):''}</div>`:''}</aside><div><div class="rise-attribute-grid">${attrs().map(([category,items])=>`<section class="rise-panel rise-category"><h3><span class="rise-category-title">${graphic('category',category)}${esc(category)}</span><span>${avg(p,items)}</span></h3>${items.map(a=>{const u=api().upgradePreview(state(),p.id,a.key);return `<div class="rise-rating"><div><span>${esc(a.name)}</span><small>${u.current} → ${u.next} · max ${u.cap}</small></div>${bar(u.current)}<button type="button" class="rise-upgrade" data-rise="upgrade" data-id="${p.id}" data-key="${a.key}" ${u.available?'':'disabled'} aria-label="${esc(a.name)}: ${u.current} to ${u.next} for ${u.cost} upgrade points">${u.current>=u.cap?'MAX':`+${u.gain} · ${u.cost} UP`}</button></div>`;}).join('')}</section>`).join('')}</div><section class="rise-panel rise-ability-panel">${heading('SPECIALIZE. STAND OUT.','Signature ability tree','Meet rating requirements, then invest upgrade points. Choose at most two branches.')}<div class="rise-ability-grid">${Object.keys(api().ABILITIES).map(key=>{const a=api().abilityPreview(state(),p.id,key);return `<article class="rise-ability ${a.rank?'is-owned':''}"><div class="rise-ability-top"><span>${esc(title(a.branch))}</span><b aria-label="Rank ${a.rank} of 3">${[1,2,3].map(i=>`<i class="${i<=a.rank?'filled':''}">◆</i>`).join('')}</b></div><div class="rise-ability-title">${graphic('ability',key)}<h4>${esc(a.name)}</h4></div><p>${esc(a.description)}</p><div class="rise-requirements">${Object.entries(a.requirements).map(([k,v])=>`<span class="${p.ratings[k]>=v+a.rank*4?'is-met':''}">${esc(title(k))} ${v+a.rank*4}</span>`).join('')}</div>${a.requires?`<small>Requires ${esc(api().ABILITIES[a.requires].name)}</small>`:''}${button(a.rank>=3?'Mastered':`${a.rank?'Rank '+a.nextRank:'Unlock'} · ${a.cost} UP`,'ability',`data-id="${p.id}" data-key="${key}" ${a.available?'':'disabled'}`)}${a.missing.length?`<small>${esc(a.missing.join(' · '))}</small>`:''}</article>`;}).join('')}</div></section></div></div>`;
  }
  function scoutingReport(p){return `<section class="rise-panel rise-scout-report"><div>${heading('SCOUTING FILE',p.name,p.scoutingReport)}<div class="rise-scout-notes"><p><b>Strengths</b>${esc(p.strengths.map(title).join(' · '))}</p><p><b>Watch for</b>${esc(p.weaknesses.map(title).join(' · '))}</p><p><b>Signature potential</b>${esc(p.abilityPotential.map(key=>api().ABILITIES[key].name).join(' · '))}</p></div></div><div class="rise-scout-summary"><strong>${p.overall}<small>OVERALL</small></strong><span>${esc(p.tier)} · ${p.potential} potential</span>${button(money(p.signingCost)+' · Sign athlete','sign',`data-id="${p.id}" ${p.signingCost>state().currency||state().roster.length>=10?'disabled':''}`,'is-primary')}</div></section>`;}
  function marketView(){
    const all=api().market(state());let pool=all.filter(p=>(ui.tier==='all'||p.tier===ui.tier)&&(ui.position==='all'||p.position===ui.position)&&(!ui.affordable||p.signingCost<=state().currency)&&`${p.name} ${archetype(p)} ${p.scoutingReport}`.toLowerCase().includes(ui.search.toLowerCase()));
    pool.sort((a,b)=>ui.sort==='overall'?b.overall-a.overall:ui.sort==='potential'?b.potential-a.potential:ui.sort==='price'?a.signingCost-b.signingCost:b.overall/Math.max(1,b.signingCost)-a.overall/Math.max(1,a.signingCost));
    ui.page=Math.min(ui.page,Math.max(0,Math.ceil(pool.length/12)-1));const prospect=all.find(p=>p.id===ui.compare);
    return `${artHeading('THE SCOUTING CENTER','Find your missing piece.',`${all.length} available recruits · ${10-state().roster.length} roster spots · ${money(state().currency)} to build with`,'scouting')}<section class="rise-panel rise-market-filters"><label class="rise-search">Search athletes<input id="riseMarketSearch" data-rise-input="search" type="search" value="${esc(ui.search)}" placeholder="Name, archetype, scouting style…"></label><label>Tier<select data-rise-change="tier">${option({all:'Every tier',...Object.fromEntries([...new Set(all.map(p=>p.tier))].map(t=>[t,t]))},ui.tier)}</select></label><label>Position<select data-rise-change="position">${option({all:'Every position',...Object.fromEntries([...new Set(all.map(p=>p.position))].map(t=>[t,t]))},ui.position)}</select></label><label>Sort<select data-rise-change="sort">${option({value:'Best value',price:'Signing cost',overall:'Overall rating',potential:'Potential'},ui.sort)}</select></label><label class="rise-check"><input type="checkbox" data-rise-change="affordable" ${ui.affordable?'checked':''}> Within budget</label></section>${prospect?scoutingReport(prospect):''}<div class="rise-result-count">${pool.length} matching athletes <span>New prospects arrive as your campaign develops.</span></div><div class="rise-player-grid">${pool.length?pool.slice(ui.page*12,(ui.page+1)*12).map(p=>card(p,'market')).join(''):'<div class="rise-empty"><strong>No matching prospects.</strong><p>Try a different position, tier, or budget filter.</p></div>'}</div><div class="rise-pagination">${button('← Previous','market-page',`data-page="${ui.page-1}" ${ui.page>0?'':'disabled'}`)}<span>Page ${ui.page+1} / ${Math.max(1,Math.ceil(pool.length/12))}</span>${button('Next →','market-page',`data-page="${ui.page+1}" ${(ui.page+1)*12<pool.length?'':'disabled'}`)}</div>${prospect?comparison():''}`;
  }
  function scheduleView(){
    const s=state(),{game}=match();
    return `${heading('FIVE DIVISIONS. ONE LEGACY.','The road to glory.','Win the league, survive the playoffs, and carry your team into a stronger division.')}<ol class="rise-division-track">${api().DIVISIONS.map((d,i)=>`<li class="${i<s.season.division?'is-complete':i===s.season.division?'is-current':'is-locked'}"><div class="rise-division-badge">${graphic('division',d.id)}<span>${i<s.season.division?'✓ CLEARED':`DIVISION ${String(i+1).padStart(2,'0')}`}</span></div><div><strong>${esc(d.name)}</strong><small>${i<s.season.division?'Division cleared':i===s.season.division?'Current competition':'Win the previous championship'}</small></div></li>`).join('')}</ol><div class="rise-hub-grid"><section class="rise-panel">${heading(`SEASON ${s.season.number} / ${title(s.season.phase)}`,division().name)}<div class="rise-schedule">${s.season.schedule.map((g,i)=>{const result=s.season.completed.find(x=>x.id===g.id),opp=api().opponent(s,g);return `<div class="rise-fixture ${g.id===game?.id?'is-next':''}"><span class="rise-fixture-number">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(opp.name)}</strong><small>${esc(g.kind)} · ${g.teamSize}v${g.teamSize}</small></div>${result?`<b class="${result.won?'rise-positive':'rise-negative'}">${result.won?'W':'L'} ${result.homeScore}–${result.awayScore}</b>`:g.id===game?.id?button('Prepare →','tab','data-tab="strategy"'):'<span class="rise-muted">Upcoming</span>'}</div>`;}).join('')}</div>${!game?button('Begin next season →','advance','','is-primary'):''}</section><section class="rise-panel">${heading('THE TABLE','Season standings')}${standings()}<div class="rise-reward"><b>Championships earned</b><p>${s.awards.filter(a=>/champion/i.test(a.name)).map(a=>esc(a.name)).join(' · ')||'Your first banner is waiting.'}</p></div></section></div>`;
  }
  function strategy(){
    const s=state(),{game,opponent}=match();if(!game)return heading('OFFSEASON','Your season is complete.','Head to the clubhouse to begin another season.',button('Clubhouse','tab','data-tab="hub"'));
    const c=api().chemistry(s.starters.map(athlete));
    return `${heading('MATCH PREPARATION',`Take on ${opponent.name}.`,`${game.teamSize}v${game.teamSize} · ${game.kind} · ${division().name}`)}<div class="rise-hub-grid"><section class="rise-panel"><h3>Send out your best fit.</h3>${lineupGraphic()}${lineup()}<div class="rise-form-pair"><label>Offensive identity<select data-rise-change="offense">${option(offenses,s.team.offense)}</select></label><label>Defensive focus<select data-rise-change="defense">${option(defenses,s.team.defense)}</select></label></div><p class="rise-tactic-copy">${esc(typeof OFFENSIVE_STYLES!=='undefined'?OFFENSIVE_STYLES[s.team.offense]?.description||'Play to your lineup’s strengths.':'Play to your lineup’s strengths.')}</p><div class="rise-role-list">${roster().filter(p=>s.starters.includes(p.id)).map(p=>`<label><span>${esc(p.name)}<small>${esc(archetype(p))}</small></span><select data-rise-change="role" data-id="${p.id}">${roleOptions(p.role)}</select>${assignmentHint(p)}</label>`).join('')}</div><div class="rise-priorities">${s.starters.map(id=>{const p=athlete(id);return `<label>${esc(p.name)} / offensive priority<select data-rise-change="priority" data-id="${id}">${option({1:'Supporting option',2:'Secondary option',3:'First option'},String(p.priority||1))}</select></label>`;}).join('')}</div><label>Substitution priority<select data-rise-change="substitution">${option({balanced:'Balanced rotation',fresh_legs:'Fresh legs first',matchup:'Best matchup first',starters:'Keep starters on court'},s.team.substitution)}</select></label><div class="rise-synergies">${c.synergies.map(x=>`<p><b>${esc(x.name)}</b>${esc(x.effect)}</p>`).join('')||'<p>Pair a passer with a shooter, a slasher with a stretch big, or a stopper with a rim protector to create a team connection.</p>'}</div><p class="rise-muted">Strengths: ${esc(c.strengths.join(', '))}. Watch: ${esc(c.weaknesses.join(', '))}.</p></section><section class="rise-panel rise-opponent-scout"><span class="rise-kicker">OPPOSITION SCOUTING${opponent.rival?' / RIVAL':''}</span><h3>${esc(opponent.name)}</h3><p>${esc(opponent.identity)}</p>${opponent.rivalryRecord?`<p class="rise-rivalry">CAREER MATCHUP / ${num(opponent.rivalryRecord.wins)} wins · ${num(opponent.rivalryRecord.losses)} losses</p>`:''}<div class="rise-match-numbers">${metric('Overall',theirOverall(opponent))}${metric('Offense',offenses[opponent.offense])}</div><div class="rise-opponent-lineup">${opponent.players.map(p=>`<div>${portrait(p,true)}<span><b>${esc(p.name)}</b><small>${esc(archetype(p))} · ${p.overall} OVR</small></span></div>`).join('')}</div><div class="rise-matchups"><h4>Defensive assignments</h4>${s.starters.slice(0,game.teamSize).map(id=>`<label>${esc(athlete(id).name)}<select data-rise-change="matchup" data-id="${id}">${option({auto:'Automatic matchup',...Object.fromEntries(opponent.players.slice(0,game.teamSize).map(p=>[p.id,p.name]))},s.team.matchups[id]||'auto')}</select></label>`).join('')}</div><div class="rise-play-footer">${button('Take the court →','play','','is-primary')}<small>Your game plan and development ratings apply to every teammate.</small></div></section></div>`;
  }
  function training(){
    const p=selected();return `${artHeading('PUT IN THE WORK','The next leap starts here.','Practice with the same shooting mechanics and court physics used in your campaign.','training',picker())}<div class="rise-training-grid">${api().TRAINING.map((d,i)=>{const tier=Math.min(3,1+(p.training?.[d.id]?.tier||0)),plan=api().trainingPlan(state(),p.id,d.id,tier);return `<section class="rise-panel rise-drill"><div class="rise-drill-art">${graphic('training',d.id)}</div><span class="rise-drill-number">${String(i+1).padStart(2,'0')}</span><span class="rise-kicker">${esc(title(d.attribute))} / TIER ${tier}</span><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p><div class="rise-chips"><span class="rise-chip">${plan.target} / ${plan.attempts} target</span><span class="rise-chip">Up to ${plan.xp} XP</span><span class="rise-chip">${plan.rating} skill rating</span>${tier===3?'<span class="rise-chip">Compatible signature tuition reward</span>':''}</div>${button('Start drill →','train',`data-key="${d.id}" data-id="${p.id}"`)}</section>`;}).join('')}</div><p class="rise-muted">Successful reps award modest, skill-specific progress. Up to three rewarded sessions per athlete each game week; advanced tiers unlock as you improve.</p>`;
  }
  function statistics(){
    const players=roster(),totals=Object.values(state().players).reduce((t,p)=>{Object.entries(p.stats).forEach(([k,v])=>t[k]=(t[k]||0)+v);return t;},{}),pct=(m,a)=>a?num(m/a*100)+'%':'—';
    return `${heading('THE NUMBERS TELL YOUR STORY','Every contribution counts.','Points, playmaking, rebounding, and defensive stops all build a player’s career.')}<div class="rise-stats-metrics">${metric('Career points',totals.points)}${metric('Assists',totals.assists)}${metric('Rebounds',totals.rebounds)}${metric('Field goals',pct(totals.fgm,totals.fga))}${metric('Steals + blocks',totals.steals+totals.blocks)}</div><section class="rise-panel"><div class="rise-table-scroll"><table class="rise-table rise-career-table"><caption>Career statistics / current roster</caption><thead><tr><th>Athlete</th><th>GP</th><th>PTS</th><th>AST</th><th>REB</th><th>FG%</th><th>3P%</th><th>STL</th><th>BLK</th><th>LVL</th><th>XP</th></tr></thead><tbody>${players.map(p=>{const t=p.stats;return `<tr><th scope="row">${esc(p.name)}<small>${esc(archetype(p))}</small></th><td>${t.games}</td><td>${t.points}</td><td>${t.assists}</td><td>${t.rebounds}</td><td>${pct(t.fgm,t.fga)}</td><td>${pct(t.threeMade,t.threeAttempts)}</td><td>${t.steals}</td><td>${t.blocks}</td><td>${p.level}</td><td>${p.xp}</td></tr>`;}).join('')}</tbody></table></div></section><section class="rise-panel">${heading('THE TROPHY CABINET','Milestones & rewards')}<div class="rise-chips">${state().awards.map(a=>`<span class="rise-chip">${esc(a.name)} · Season ${a.season}</span>`).join('')||'<p class="rise-muted">Win rivalries and championships to earn team cosmetics and career awards.</p>'}</div></section>`;
  }
  function transferPreview(){
    const preview=ui.importPreview;if(!preview)return '';
    const s=preview.summary;
    return `<section class="rise-panel rise-transfer-preview" aria-labelledby="riseImportHeading"><p class="rise-kicker">REVIEW YOUR SAVE</p><h3 id="riseImportHeading" tabindex="-1">Import ${esc(s.teamName)}?</h3><p>${esc(s.division)} · Season ${s.season} · ${s.wins} wins / ${s.losses} losses · ${money(s.currency)}</p><p>Captain: ${esc(s.captainName)} · ${s.completedGames} games completed this season</p><ul class="rise-transfer-roster">${s.roster.map(p=>`<li><strong>${esc(p.name)}</strong><span>${p.overall} OVR · Level ${p.level} · ${esc(title(p.role))}</span></li>`).join('')}</ul><p class="rise-transfer-warning">${state()?`This will replace <strong>${esc(state().team.name)}</strong> on this device. Your current campaign will be kept as a backup.`:'This will continue the imported campaign on this device.'} Player development, assignments, roster, results and club funds come with the save.</p><div class="rise-actions">${button(state()?'Replace current campaign':'Import campaign','import-confirm','','is-primary')}${button('Cancel import','import-cancel')}</div></section>`;
  }
  function transferControls(){
    return `<div class="rise-save-actions">${state()?button('Export save','export-save'):''}${button('Import save','import-open')}<input type="file" id="riseImportFile" data-rise-change="import-file" accept=".json,application/json" aria-label="Choose a Rise to Glory save file" hidden></div>`;
  }
  async function readImport(file){
    if(!file)return;
    const readId=++ui.importReadId;ui.importPreview=null;
    if(file.size>api().MAX_SAVE_BYTES){ui.notice='This save file is too large. The limit is 8 MB.';render();return;}
    try{
      const serialized=await file.text();if(readId!==ui.importReadId)return;
      const checked=api().inspectSave(serialized);ui.notice=checked.message;
      if(checked.ok)ui.importPreview={serialized,summary:checked.summary};
    }catch(_error){if(readId!==ui.importReadId)return;ui.notice='This file could not be read. Your current save has not changed.';}
    render();if(ui.importPreview)document.getElementById('riseImportHeading')?.focus();
  }
  function downloadSave(){
    const exported=api().exportSave(state());if(!exported.ok){ui.notice=exported.message;render();return;}
    const url=URL.createObjectURL(new Blob([exported.serialized],{type:'application/json'})),link=document.createElement('a');
    link.href=url;link.download=exported.filename;link.hidden=true;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
    ui.notice='Save downloaded. Keep this file to move your franchise to another device.';render();
  }
  function render(){
    if(!screen)return;stopPreview();
    const s=state(),active=document.activeElement,focus=active?.id,selection=active?.selectionStart,focusedData=active?.dataset?{...active.dataset}:null;
    const primary=s?.team.primaryColor||ui.draft?.primaryColor||'#6aa8e8',secondary=s?.team.secondaryColor||ui.draft?.secondaryColor||'#f2b19a';
    screen.style.setProperty('--rise-brand-primary',primary);screen.style.setProperty('--rise-brand-secondary',secondary);
    screen.style.setProperty('--rise-primary',readableAccent(primary,'#a8cbed'));screen.style.setProperty('--rise-secondary',readableAccent(secondary,'#f2b19a'));
    const views={hub,roster:rosterView,develop:development,market:marketView,schedule:scheduleView,strategy,training,stats:statistics};
    screen.innerHTML=`<header class="rise-topbar">${button('← Main menu','back','','rise-back')}<div class="rise-wordmark">BB2 <span>RISE TO GLORY</span></div>${s?`<div class="rise-balance"><small>CLUB FUNDS / LEVEL ${s.level}</small><b>${money(s.currency)}</b></div>`:'<span class="rise-kicker">A TEAM WORTH BUILDING</span>'}</header>${s?`<nav class="rise-nav" aria-label="Rise to Glory sections">${tabs.map(([key,label])=>`<button type="button" data-rise="tab" data-tab="${key}" aria-current="${ui.tab===key?'page':'false'}" class="${ui.tab===key?'active':''}">${icon(key)}<span>${label}</span></button>`).join('')}</nav>`:''}<div class="rise-notice" role="status" aria-live="polite" ${ui.notice?'':'hidden'}>${esc(ui.notice)}${ui.notice?button('×','dismiss','aria-label="Dismiss notification"'):''}</div><div class="rise-content">${transferPreview()}${s?(views[ui.tab]||hub)():creation()}</div><footer class="rise-footer"><div><span>HALF COURT. FULL CAREER.</span><p>${s?'Progress saves automatically on this device.':'Build from the ground up.'}</p></div>${transferControls()}</footer>`;
    if(focus){const next=document.getElementById(focus);if(next){next.focus({preventScroll:true});if(typeof selection==='number'&&next.type==='search')next.setSelectionRange(selection,selection);}}
    if(!focus&&focusedData){const keys=['rise','riseChange','id','key','tab','slot'],selector=keys.filter(key=>focusedData[key]!==undefined).map(key=>'[data-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+'="'+focusedData[key]+'"]').join('');if(selector)screen.querySelector(selector)?.focus({preventScroll:true});}
    if(s&&(ui.tab==='hub'||ui.tab==='develop'))startPreview(ui.tab==='develop'?selected():athlete(s.captainId));
  }
  function readDraft(){const form=document.getElementById('riseCreationForm');if(form)new FormData(form).forEach((value,key)=>ui.draft[key]=key==='captainNumber'?Math.max(0,Math.min(99,num(value))):key==='captainSkin'?Number(value):value);}
  function click(event){
    const b=event.target.closest('[data-rise]');if(!b||b.disabled)return;
    const action=b.dataset.rise,id=b.dataset.id,key=b.dataset.key;
    if(action==='export-save'){downloadSave();return;}
    if(action==='import-open'){document.getElementById('riseImportFile')?.click();return;}
    if(action==='import-cancel'){ui.importReadId++;ui.importPreview=null;ui.notice='Import cancelled. Your current save has not changed.';render();return;}
    if(action==='import-confirm'){
      if(!ui.importPreview)return;
      const result=api().importSave(ui.importPreview.serialized);ui.notice=result.message;
      if(result.ok){riseState=result.state;ui.selected=state().captainId;ui.compare=null;ui.tab='hub';ui.release=null;ui.importPreview=null;ui.notice=result.backedUp?'Campaign imported. Your previous campaign is kept as a backup.':'Campaign imported. Your franchise is ready to continue.';buildRiseUI();}
      render();return;
    }
    if(action==='back'){stopPreview();if(typeof leaveRiseMatch==='function')leaveRiseMatch();showPrimaryMenu();return;}
    if(action==='tab'){ui.tab=b.dataset.tab;ui.notice='';ui.release=null;render();return;}
    if(action==='dismiss'){ui.notice='';render();return;}
    if(action==='create-submit'){document.getElementById('riseCreationForm').requestSubmit();return;}
    if(action==='logo'){readDraft();ui.draft.logo=id;render();return;}
    if(action==='rookie'){readDraft();const ids=ui.draft.starterIds,index=ids.indexOf(id);if(index>=0)ids.splice(index,1);else if(ids.length<3)ids.push(id);else ui.notice='Choose three rookies. Remove one selection before adding another.';render();return;}
    if(action==='develop'){ui.selected=id;ui.tab='develop';ui.release=null;render();return;}
    if(action==='compare'){ui.selected=id;ui.tab='roster';render();screen.querySelector('.rise-compare')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}
    if(action==='scout'){ui.compare=id;render();screen.querySelector('.rise-scout-report')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}
    if(action==='sign'){mutate('sign',id);return;}
    if(action==='market-page'){ui.page=num(b.dataset.page);render();screen.querySelector('.rise-market-filters')?.scrollIntoView({block:'nearest'});return;}
    if(action==='upgrade'||action==='ability'){if(mutate(action==='upgrade'?'upgrade':'learnAbility',id,key))screen.querySelector('.rise-detail-name')?.classList.add('rise-level-flash');return;}
    if(action==='release'){if(ui.release!==id){ui.release=id;render();}else{ui.release=null;if(mutate('release',id)){ui.selected=state().roster[0];render();}}return;}
    if(action==='cancel-release'){ui.release=null;render();return;}
    if(action==='advance'){mutate('advanceSeason');return;}
    if(action==='play'){stopPreview();if(typeof startRiseMatch==='function')startRiseMatch();return;}
    if(action==='train'){stopPreview();if(typeof startRiseTraining==='function')startRiseTraining(key,id);return;}
  }
  function change(event){
    const target=event.target,action=target.dataset.riseChange;
    if(action==='import-file'){const file=target.files?.[0];target.value='';readImport(file);return;}
    if(!action){if(!state()){readDraft();if(target.type==='color')render();}return;}
    if(action==='selected'){ui.selected=target.value;ui.release=null;render();return;}
    if(action==='compare'){ui.compare=target.value;render();return;}
    if(action==='role'){mutate('setRole',target.dataset.id,target.value);return;}
    if(action==='priority'){const p=athlete(target.dataset.id);mutate('setRole',p.id,p.role,num(target.value));return;}
    if(action==='lineup'){const ids=[...state().starters],slot=num(target.dataset.slot),other=ids.indexOf(target.value);if(other>=0)ids[other]=ids[slot];ids[slot]=target.value;mutate('setStarters',ids);return;}
    if(['offense','defense','substitution'].includes(action)){mutate('setStrategy',{[action]:target.value});return;}
    if(action==='matchup'){const matchups={...state().team.matchups};if(target.value==='auto')delete matchups[target.dataset.id];else matchups[target.dataset.id]=target.value;mutate('setStrategy',{matchups});return;}
    if(['tier','position','sort'].includes(action)){ui[action]=target.value;ui.page=0;}
    if(action==='affordable'){ui.affordable=target.checked;ui.page=0;}
    render();
  }
  function submit(event){
    if(event.target.id==='riseCreationForm'){
      event.preventDefault();readDraft();if(ui.draft.starterIds.length!==3)return;
      riseState=api().create(ui.draft);ui.selected=state().captainId;ui.tab='hub';save('Your franchise is ready. Set your lineup and take on Street League.');buildRiseUI();render();return;
    }
    if(event.target.id==='riseCosmeticsForm'){
      event.preventDefault();const form=new FormData(event.target),p=selected();['jerseyStyle','primaryColor','secondaryColor','cosmetic'].forEach(key=>state().team[key]=form.get(key));p.appearance.number=String(Math.max(0,Math.min(99,num(form.get('number')))));p.equipment=p.equipment||{};
      ['headband','sleeve'].forEach(key=>p.equipment[key]={enabled:form.get(key)==='on',color:state().team.secondaryColor});save('Appearance saved. Your uniform will be worn in campaign games.');render();
    }
  }
  function stopPreview(){
    if(frameId)cancelAnimationFrame(frameId);frameId=0;observer?.disconnect();observer=null;if(!preview)return;
    if(typeof disposePlayerModel==='function')disposePlayerModel(preview.player);
    const geometries=new Set(),materials=new Set(),textures=new Set();
    preview.scene.traverse(node=>{if(node.geometry)geometries.add(node.geometry);for(const material of Array.isArray(node.material)?node.material:[node.material]){if(!material)continue;materials.add(material);Object.values(material).forEach(value=>{if(value?.isTexture)textures.add(value);});}});
    geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());preview.renderer.dispose();preview.renderer.forceContextLoss();preview=null;
  }
  function startPreview(p){
    const host=document.getElementById('riseModelPreview');if(!host||!p||typeof THREE==='undefined'||typeof createCharacter!=='function')return;
    try{
      const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(32,1,.1,30),renderer=new THREE.WebGLRenderer({alpha:true,antialias:false,powerPreference:'low-power'});
      renderer.setPixelRatio(Math.min(1.5,window.devicePixelRatio||1));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor(0x000000,0);
      const profile=api().toProfile(p,state().team),player=createCharacter(profile,new THREE.Vector3(),'rise-preview',0);player.hasBall=false;player.group.rotation.y=-.25;
      if(typeof updateBasketballPlayerEquipment==='function')updateBasketballPlayerEquipment(player,{jersey:{color:state().team.primaryColor},shorts:{color:state().team.secondaryColor},accent:{color:state().team.secondaryColor},...(p.equipment||{})});
      scene.add(player.group);scene.add(new THREE.HemisphereLight(0xdde9ff,0x293142,2.3));const key=new THREE.DirectionalLight(0xffffff,2.6);key.position.set(-3,4,5);scene.add(key);const rim=new THREE.DirectionalLight(0xa9c8ff,2);rim.position.set(3,3,-2);scene.add(rim);
      camera.position.set(0,1.45,5.1*profile.height);camera.lookAt(0,1.2*profile.height,0);preview={renderer,scene,camera,player};host.replaceChildren(renderer.domElement);renderer.domElement.setAttribute('aria-hidden','true');
      const resize=()=>{const w=Math.max(1,host.clientWidth),h=Math.max(1,host.clientHeight);renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();};resize();if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(resize);observer.observe(host);}
      let last=0;const frame=now=>{if(!preview||!screen.classList.contains('active')||document.getElementById('menu').style.display==='none'){stopPreview();return;}frameId=requestAnimationFrame(frame);if(document.hidden||now-last<80)return;const dt=Math.min(.1,(now-last)/1000);last=now;if(typeof attachPlayerModel==='function'&&!player.playerModel)attachPlayerModel(player);if(player.playerModel){setBasketballPlayerAction(player.playerModel,'idle');player.playerModel.mixer.update(dt);}renderer.render(scene,camera);};frameId=requestAnimationFrame(frame);
    }catch(error){stopPreview();host.innerHTML=portrait(p);console.warn('Campaign preview is using the jersey portrait.',error);}
  }
  function buildRiseUI(){
    if(!api()||!document.getElementById('menuBox'))return;
    screen=document.getElementById('riseCampaignScreen');
    if(!screen){screen=document.createElement('div');screen.id='riseCampaignScreen';screen.className='menuScreen rise-screen';document.getElementById('menuBox').appendChild(screen);screen.addEventListener('click',click);screen.addEventListener('change',change);screen.addEventListener('submit',submit);screen.addEventListener('input',event=>{if(event.target.dataset.riseInput==='search'){ui.search=event.target.value;ui.page=0;render();}});}
    let entry=document.getElementById('primaryRiseBtn');
    if(!entry){const tile=document.createElement('section');tile.className='rise-menu-card';tile.innerHTML=`${art('hero','rise-menu-art')}<div class="rise-menu-emblem">${logo()}</div><div class="rise-menu-copy"><span class="mode-card-kicker">YOUR TEAM. YOUR LEGACY.</span><h2>Rise to Glory</h2><p>Recruit your squad. Build a star. Chase the championship.</p></div><button type="button" id="primaryRiseBtn">Build your franchise →</button>`;document.querySelector('.primary-extra-grid')?.insertAdjacentElement('afterend',tile);entry=tile.querySelector('button');}
    if(entry){entry.onclick=()=>showRiseCampaign();entry.textContent=state()?'Continue franchise →':'Build your franchise →';}
  }
  function showRiseCampaign(tab='hub',message=''){
    stopPreview();if(typeof leaveRiseMatch==='function')leaveRiseMatch();buildRiseUI();if(!screen)return;
    if(!state())riseState=api().load();
    if(typeof gameStarted!=='undefined')gameStarted=false;if(typeof gamePaused!=='undefined')gamePaused=false;if(typeof tutorialMode!=='undefined')tutorialMode=false;
    if(typeof inputManager!=='undefined')inputManager.clearAll();if(typeof tutorialCoach!=='undefined')tutorialCoach?.stop();document.body.classList.remove('tutorial-active','touch-controls-active');if(typeof isTournamentGame!=='undefined')isTournamentGame=false;
    ui.tab=tabs.some(([key])=>key===tab)?tab:'hub';ui.notice=message||'';showMenuScreen('riseCampaignScreen');render();const h=screen.querySelector('h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}
  }
  root.buildRiseUI=buildRiseUI;root.showRiseCampaign=showRiseCampaign;root.stopRisePreview=stopPreview;
})(typeof window!=='undefined'?window:globalThis);
